<?php defined('BASEPATH') or exit('No direct script access allowed');$milestoneEscape=static fn($v)=>htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8'); ?>
<section id="portal-project-milestones"><h2>Marcos do projeto</h2><?php if(!$project_milestones['items']){ ?><p>Nenhum marco publicado.</p><?php }foreach($project_milestones['items'] as $milestone){ ?><article data-milestone="<?= (int)$milestone['id']; ?>"><h3><?= $milestoneEscape($milestone['name']); ?></h3><p>Início: <time><?= $milestoneEscape($milestone['start_date']); ?></time> · Prazo: <time><?= $milestoneEscape($milestone['due_date']); ?></time> · <?= $milestone['done']?'Concluído':'Em andamento'; ?></p><?php if(array_key_exists('description',$milestone)){ ?><p style="white-space:pre-wrap"><?= $milestoneEscape($milestone['description']); ?></p><?php }if(array_key_exists('published_logged_seconds',$milestone)){$seconds=$milestone['published_logged_seconds']; ?><p>Tempo encerrado publicado: <?= intdiv($seconds,3600); ?>h <?= intdiv($seconds%3600,60); ?>min <?= $seconds%60; ?>s.</p><p>Esta soma considera apenas os tempos publicados das tarefas publicadas deste marco.</p><?php } ?></article><?php } ?></section>
